 static T Get<T>(IAsyncOperation<T> op){var deadline=DateTime.UtcNow.AddSeconds(10);while(op.Status==AsyncStatus.Started&&DateTime.UtcNow<deadline)Thread.Sleep(25);if(op.Status==AsyncStatus.Started){op.Cancel();throw new TimeoutException("Bluetooth discovery timeout");}if(op.Status!=AsyncStatus.Completed)throw new Exception("Bluetooth discovery failed: "+op.ErrorCode);return op.GetResults();}
