 sealed class Endpoint:EndPoint {
  readonly ulong address;readonly int channel;public Endpoint(ulong a,int c){address=a;channel=c;}
  public override AddressFamily AddressFamily{get{return (AddressFamily)32;}}
  public override SocketAddress Serialize(){var s=new SocketAddress(AddressFamily,30);byte[] a=BitConverter.GetBytes(address),p=BitConverter.GetBytes(channel);for(int i=0;i<8;i++)s[2+i]=a[i];for(int i=0;i<4;i++)s[26+i]=p[i];return s;}
  public override EndPoint Create(SocketAddress value){if(value==null||value.Family!=(AddressFamily)32||value.Size<30)throw new ArgumentException("Invalid Bluetooth socket address");ulong parsed=0;for(int i=0;i<8;i++)parsed|=((ulong)value[2+i])<<(8*i);int port=0;for(int i=0;i<4;i++)port|=((int)value[26+i])<<(8*i);return new Endpoint(parsed,port);}
