 static int Main(){var devices=new List<BluetoothDevice>();var services=new List<RfcommDeviceService>();try{if(Busy())throw new Exception("Call in progress; diagnostic not started");ulong address=0;var paired=Get(DeviceInformation.FindAllAsync(BluetoothDevice.GetDeviceSelectorFromPairingState(true)));foreach(var info in paired){BluetoothDevice device=null;try{device=Get(BluetoothDevice.FromIdAsync(info.Id));}catch{continue;}if(device==null)continue;devices.Add(device);var result=Get(device.GetRfcommServicesForIdAsync(RfcommServiceId.FromUuid(new Guid("0000111f-0000-1000-8000-00805f9b34fb")),BluetoothCacheMode.Cached));foreach(var service in result.Services){services.Add(service);address=device.BluetoothAddress;}}Log("Gateways="+services.Count);if(services.Count!=1)throw new Exception("Expected one paired HFP gateway");var attrs=Get(services[0].GetSdpRawAttributesAsync(BluetoothCacheMode.Cached));if(!attrs.ContainsKey(4))throw new Exception("SDP protocol descriptor missing");byte[] raw=new byte[attrs[4].Length];using(var r=DataReader.FromBuffer(attrs[4]))r.ReadBytes(raw);int channel=HfpSdp.RfcommChannel(raw);Log("RfcommChannel="+channel);Log("AddressValid="+(address>0&&address<=0xFFFFFFFFFFFFUL));string host=System.Text.RegularExpressions.Regex.Replace(services[0].ConnectionHostName.RawName,"[^0-9A-Fa-f]","");Log("AddressMatchesService="+String.Equals(host,address.ToString("X12"),StringComparison.OrdinalIgnoreCase));using(var transport=new Channel(address,channel)){Log("RFCOMM=Connected");var protocol=new HfpProtocol(transport);var state=protocol.Initialize();Log("HFP=Ready;Idle="+state.Idle);}Log("No calls or audio-routing commands performed");return 0;}catch(Exception ex){var socket=ex as SocketException;Log("Error="+ex.HResult.ToString("X8")+";"+ex.Message+(socket==null?"":";SocketError="+socket.SocketErrorCode));return 1;}finally{foreach(var service in services)service.Dispose();foreach(var device in devices)device.Dispose();Log("DiagnosticFinished");}}
